import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Goftego — plataforma de chat autoalojada","description":"Plataforma de chat ligera autoalojada: canales, fan-out WebSocket en tiempo real, auth JWT, presencia e indicadores de escritura — un archivo SQLite, interfaz bilingüe fa/en con RTL.","frontmatter":{"title":"Goftego — plataforma de chat autoalojada","description":"Plataforma de chat ligera autoalojada: canales, fan-out WebSocket en tiempo real, auth JWT, presencia e indicadores de escritura — un archivo SQLite, interfaz bilingüe fa/en con RTL."},"headers":[],"relativePath":"es/projects/goftego/index.md","filePath":"es/projects/goftego/index.md"}`),a={name:`es/projects/goftego/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="goftego-—-plataforma-de-chat-autoalojada" tabindex="-1">Goftego — plataforma de chat autoalojada <a class="header-anchor" href="#goftego-—-plataforma-de-chat-autoalojada" aria-label="Permalink to “Goftego — plataforma de chat autoalojada”">​</a></h1><p><strong><a href="https://github.com/Godde3s/goftego" target="_blank" rel="noreferrer">Goftego</a></strong> (گفتگو — <em>conversación</em>) es lo que una comunidad pequeña tiene en vez de entregar sus conversaciones a un SaaS: <strong>chat autoalojado con un solo comando y datos propios</strong>. Canales, entrega en tiempo real, recuentos de presencia, indicadores de escritura, auth JWT con contraseñas bcrypt — todo en <strong>un archivo SQLite</strong> con WAL, sin servicios externos.</p><h2 id="el-stack" tabindex="-1">El stack <a class="header-anchor" href="#el-stack" aria-label="Permalink to “El stack”">​</a></h2><ul><li><strong>Servidor</strong> — Node.js (ESM): API REST con Express, hub WebSocket (<code>join</code> / <code>leave</code> / <code>typing</code> / <code>post</code> → persistir → fan-out), <code>better-sqlite3</code>, bcrypt cost 12, JWT verificado en REST y en el handshake WS.</li><li><strong>Cliente</strong> — SPA en Vue 3: store reactivo sin librería de estado, UI bilingüe <strong>fa (RTL) / en</strong>, tema oscuro, móvil incluido.</li><li><strong>Despliegue</strong> — Dockerfile multi-etapa + <code>docker compose up</code>.</li></ul><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # → http://localhost:3000</span></span></code></pre></div><h2 id="detalles-que-me-costaron" tabindex="-1">Detalles que me costaron <a class="header-anchor" href="#detalles-que-me-costaron" aria-label="Permalink to “Detalles que me costaron”">​</a></h2><p>Los mensajes que llegan por REST y por WebSocket fluyen por <strong>una sola ruta de persistencia</strong>, así que el broadcast y el INSERT nunca discrepan. El hub re-verifica JWTs por conexión, la presencia se actualiza al salir o caerse, y el cliente Vue es persa-first: <code>&lt;html dir=&quot;rtl&quot;&gt;</code>, fuente Vazirmatn — el inglés está a un clic.</p><p><strong>7 tests con vitest</strong> cubren auth, CRUD de canales, paginación y validación. Es mi build full-stack de referencia: base de datos, API, tiempo real, SPA, i18n y contenedores — el ciclo completo. Licencia MIT.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};